import * as THREE from './node_modules/three/build/three.module.js';
import { makeGoblin } from './creature.js';
const q = new URLSearchParams(location.search);
const W = 1440, H = 810;
const r = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
r.setPixelRatio(window.devicePixelRatio); r.setSize(W, H); r.outputColorSpace = THREE.SRGBColorSpace;
r.toneMapping = THREE.ACESFilmicToneMapping; r.toneMappingExposure = 1.0;
r.shadowMap.enabled = true; r.shadowMap.type = THREE.PCFSoftShadowMap;
document.getElementById('stage').appendChild(r.domElement);
const scene = new THREE.Scene(); scene.background = new THREE.Color('#1a1220');
const cam = new THREE.PerspectiveCamera(+(q.get('fov')||30), W / H, 0.05, 50);
const cp = (q.get('cam') || '0.5,1.45,1.9').split(',').map(Number); const ct = (q.get('look') || '0,1.25,0.1').split(',').map(Number);
cam.position.set(...cp); cam.lookAt(...ct);
const gob = makeGoblin(); gob.rotation.y = +(q.get('ry')||0); scene.add(gob);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshStandardMaterial({ color: '#3a2a22', roughness: 0.9 }));
floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true; scene.add(floor);
scene.add(new THREE.HemisphereLight('#6a5a90', '#2a1a10', 0.5));
const key = new THREE.SpotLight('#ffc9a0', 45, 12, 0.6, 0.5, 1.5); key.position.set(1.6, 2.6, 1.8); key.target = gob; key.castShadow = true; key.shadow.mapSize.set(2048, 2048); scene.add(key);
const rim = new THREE.DirectionalLight('#7ab0ff', 2.2); rim.position.set(-2, 2.5, -2.5); scene.add(rim);
const fill = new THREE.PointLight('#ff7a30', 3, 4); fill.position.set(-1, 1.2, 1.5); scene.add(fill);
r.render(scene, cam); window.__ready = true;
